<script setup lang="ts">
import { onMounted, ref } from 'vue';import { useRoute } from 'vue-router';import dayjs from 'dayjs';import { ElMessage } from 'element-plus';import { http } from '../api/http';import StatusTag from '../components/StatusTag.vue';import type { Booking } from '../types';
const route=useRoute();const booking=ref<Booking>();async function load(){booking.value=(await http.get(`/bookings/${route.params.id}`)).data}async function action(name:string,label:string){await http.post(`/bookings/${route.params.id}/${name}`);ElMessage.success(`${label}成功`);load()}onMounted(load);
</script>
<template><div v-if="booking" class="page"><div class="page-header"><div><h2>预约详情</h2><p>{{booking.code}}</p></div><StatusTag :status="booking.status"/></div><div class="two-column"><section class="panel"><div class="detail-head"><h3>{{booking.title}}</h3><p>{{booking.description||'暂无会议说明'}}</p></div><el-descriptions :column="2" border><el-descriptions-item label="会议室">{{booking.room.name}}</el-descriptions-item><el-descriptions-item label="位置">{{booking.room.location}}</el-descriptions-item><el-descriptions-item label="开始时间">{{dayjs(booking.startTime).format('YYYY-MM-DD HH:mm')}}</el-descriptions-item><el-descriptions-item label="结束时间">{{dayjs(booking.endTime).format('YYYY-MM-DD HH:mm')}}</el-descriptions-item><el-descriptions-item label="参会人数">{{booking.attendeeCount}} 人</el-descriptions-item><el-descriptions-item label="发起人">{{booking.creator.name}}</el-descriptions-item><el-descriptions-item label="参会人员" :span="2">{{booking.attendeeNames}}</el-descriptions-item><el-descriptions-item label="审批意见" :span="2">{{booking.approvalComment||'尚无审批意见'}}</el-descriptions-item></el-descriptions><div class="action-bar"><el-button v-if="booking.status==='APPROVED'" type="primary" @click="action('check-in','签到')">会议签到</el-button><el-button v-if="booking.status==='CHECKED_IN'" type="success" @click="action('start','开始会议')">开始会议</el-button><el-button v-if="booking.status==='IN_PROGRESS'" type="success" @click="action('complete','结束会议')">结束会议</el-button></div></section><section class="panel"><div class="section-title"><h3>状态时间线</h3></div><el-timeline><el-timeline-item v-for="item in booking.audits" :key="item.id" :timestamp="dayjs(item.createdAt).format('YYYY-MM-DD HH:mm')" placement="top"><strong>{{item.user.name}}</strong><p>{{item.detail}}</p></el-timeline-item></el-timeline></section></div></div></template>
<style scoped>.detail-head{padding-bottom:20px}.detail-head h3{font-size:23px;margin:0 0 9px}.detail-head p{color:#7e8a9c;margin:0}.action-bar{margin-top:20px;display:flex;justify-content:flex-end}.el-timeline p{color:#7d899b;margin:6px 0;font-size:13px}</style>
